import { CommonModule } from '@angular/common';
import { HttpClient } from '@angular/common/http';
import { Component, OnInit } from '@angular/core';
import { environment } from '../../../../environments/environment';
import { FormBuilder, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { ToastService } from '../../../common/toast.service';

@Component({
  selector: 'app-state-about-us',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './state-about-us.component.html',
  styleUrl: './state-about-us.component.scss'
})
export class StateAboutUsComponent implements OnInit {
  aboutForm!: FormGroup;
  aboutData: any;
  selectedImages: { [key: string]: string } = {};

  constructor(
    private fb: FormBuilder,
    private http: HttpClient,
    private toastService: ToastService
  ) {}

  ngOnInit(): void {
    this.aboutForm = this.fb.group({
      stateAssociationTitle: [''],
      aboutDescription: [''],
    });

    this.fetchAboutData();
  }

  // ✅ Fetch data with toast notifications
  fetchAboutData(): void {
    // show loading toast
    this.toastService.showToast('⏳ Fetching State Association details...', 'info');

    this.http.get<any>(`${environment.apiUrl}/state-associations/about`).subscribe({
      next: (res) => {
        this.aboutData = res?.data?.data;

        this.aboutForm.patchValue({
          stateAssociationTitle: this.aboutData?.['stateAssociationTitle'] || '',
          aboutDescription: this.aboutData?.['aboutDescription'] || ''
        });

        this.selectedImages['aboutBanner'] = this.aboutData?.['aboutBanner'] || '';
        this.selectedImages['bannerPic'] = this.aboutData?.['bannerPic'] || '';

        // ✅ success toast after data load
        this.toastService.showToast('✅ State Association details loaded successfully!', 'success');
      },
      error: (err) => {
        console.error('Error fetching data:', err);
        // ❌ error toast
        this.toastService.showToast('❌ Failed to fetch State Association details.', 'danger');
      }
    });
  }

  // ✅ Handle image selection
  onImageSelected(event: any, field: 'aboutBanner' | 'bannerPic'): void {
    const file = event.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = () => {
      this.selectedImages[field] = reader.result as string;
    };
    reader.readAsDataURL(file);
  }

  // ✅ Update form submission with toast flow
  onSubmit(): void {
    const payload = {
      bannerPic: this.selectedImages['bannerPic'],
      stateAssociationTitle: this.aboutForm.value.stateAssociationTitle,
      aboutBanner: this.selectedImages['aboutBanner'],
      aboutDescription: this.aboutForm.value.aboutDescription
    };

    // show loading toast
    this.toastService.showToast('⏳ Updating State Association details...', 'info');

    this.http.patch(`${environment.apiUrl}/state-associations/about`, payload)
      .subscribe({
        next: (res) => {
          // ✅ success toast
          this.toastService.showToast('✅ State Association details updated successfully!', 'success');
          this.fetchAboutData();
        },
        error: (err) => {
          console.error('Error updating details:', err);
          // ❌ error toast
          this.toastService.showToast(err.error?.message || '❌ Failed to update details.', 'danger');
        }
      });
  }

  // ✅ Image base64 helper
  getImageUrl(base64String: string): string {
    if (!base64String) return '';
    // Add prefix only if not already present
    if (base64String.startsWith('data:image')) {
      return base64String;
    }
    return `data:image/jpeg;base64,${base64String}`;
  }
}
